<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; class ServerProperties { public const FILE = '/server.properties'; public const FIELDS = [ [ 'key' => 'motd', 'label' => 'MOTD', 'help' => 'The line under the server name in the multiplayer list. Colour codes use §.', 'type' => 'text', 'group' => 'presentation', 'max' => 240, ], [ 'key' => 'difficulty', 'label' => 'Difficulty', 'help' => 'Peaceful removes hostile mobs entirely.', 'type' => 'choice', 'group' => 'gameplay', 'options' => ['peaceful', 'easy', 'normal', 'hard'], ], [ 'key' => 'gamemode', 'label' => 'Default game mode', 'help' => 'What a player who has never joined before starts in.', 'type' => 'choice', 'group' => 'gameplay', 'options' => ['survival', 'creative', 'adventure', 'spectator'], ], [ 'key' => 'force-gamemode', 'label' => 'Force game mode on join', 'help' => 'Puts everyone back into the default mode every time they connect.', 'type' => 'toggle', 'group' => 'gameplay', ], [ 'key' => 'hardcore', 'label' => 'Hardcore', 'help' => 'Death is permanent: players are switched to spectator and cannot respawn.', 'type' => 'toggle', 'group' => 'gameplay', ], [ 'key' => 'pvp', 'label' => 'Player versus player', 'help' => 'Whether players can damage each other.', 'type' => 'toggle', 'group' => 'gameplay', ], [ 'key' => 'allow-flight', 'label' => 'Allow flying', 'help' => 'Survival flight, which mods and plugins need. Leaving it off kicks anyone who flies.', 'type' => 'toggle', 'group' => 'gameplay', ], [ 'key' => 'allow-nether', 'label' => 'Allow the Nether', 'help' => 'Turning this off closes every portal on the server.', 'type' => 'toggle', 'group' => 'gameplay', ], [ 'key' => 'spawn-monsters', 'label' => 'Spawn monsters', 'type' => 'toggle', 'group' => 'gameplay', ], [ 'key' => 'spawn-animals', 'label' => 'Spawn animals', 'type' => 'toggle', 'group' => 'gameplay', ], [ 'key' => 'spawn-npcs', 'label' => 'Spawn villagers', 'type' => 'toggle', 'group' => 'gameplay', ], [ 'key' => 'max-players', 'label' => 'Player slots', 'type' => 'number', 'group' => 'world', 'min' => 1, 'max' => 1000, ], [ 'key' => 'view-distance', 'label' => 'View distance', 'help' => 'Chunks sent to each player. The single biggest lever on memory use.', 'type' => 'number', 'group' => 'world', 'min' => 2, 'max' => 32, ], [ 'key' => 'simulation-distance', 'label' => 'Simulation distance', 'help' => 'Chunks that keep ticking. Redstone and farms stop outside it.', 'type' => 'number', 'group' => 'world', 'min' => 3, 'max' => 32, ], [ 'key' => 'spawn-protection', 'label' => 'Spawn protection', 'help' => 'Blocks around spawn only operators can build in. 0 turns it off.', 'type' => 'number', 'group' => 'world', 'min' => 0, 'max' => 1000, ], [ 'key' => 'player-idle-timeout', 'label' => 'Idle kick (minutes)', 'help' => '0 never kicks anyone for being idle.', 'type' => 'number', 'group' => 'world', 'min' => 0, 'max' => 1440, ], [ 'key' => 'enable-command-block', 'label' => 'Command blocks', 'type' => 'toggle', 'group' => 'access', ], [ 'key' => 'white-list', 'label' => 'Whitelist', 'help' => 'Only players on whitelist.json can join.', 'type' => 'toggle', 'group' => 'access', ], [ 'key' => 'enforce-whitelist', 'label' => 'Enforce whitelist immediately', 'help' => 'Kicks players already online when they are not on the list.', 'type' => 'toggle', 'group' => 'access', ], [ 'key' => 'online-mode', 'label' => 'Verify accounts with Mojang', 'help' => 'Off is what people mean by a cracked server. Use the switch above rather than this.', 'type' => 'toggle', 'group' => 'access', ], [ 'key' => 'enforce-secure-profile', 'label' => 'Require signed chat', 'help' => 'Must be off for Bedrock players, and for most offline-mode setups.', 'type' => 'toggle', 'group' => 'access', ], ]; public static function read(ServerFiles $client): ?array { $raw = $client->fileContents(self::FILE); return $raw === null ? null : self::parse($raw); } public static function write( ServerFiles $client, array $changes, ): bool { $raw = $client->fileContents(self::FILE); if ($raw === null) { return false; } return $client->writeFile(self::FILE, self::merge($raw, $changes)); } public static function parse(string $raw): array { $values = []; foreach (self::lines($raw) as $line) { $pair = self::split($line); if ($pair !== null) { $values[$pair[0]] = self::unescape($pair[1]); } } return $values; } public static function merge(string $raw, array $changes): string { $pending = $changes; $lines = self::lines($raw); foreach ($lines as $index => $line) { $pair = self::split($line); if ($pair === null || ! array_key_exists($pair[0], $pending)) { continue; } $lines[$index] = $pair[0].'='.self::escape(self::stringify($pending[$pair[0]])); unset($pending[$pair[0]]); } foreach ($pending as $key => $value) { $lines[] = $key.'='.self::escape(self::stringify($value)); } return rtrim(implode("\n", $lines), "\n")."\n"; } private static function lines(string $raw): array { return preg_split('/\r\n|\r|\n/', $raw) ?: []; } private static function split(string $line): ?array { $trimmed = ltrim($line); if ($trimmed === '' || str_starts_with($trimmed, '#') || str_starts_with($trimmed, '!')) { return null; } $parts = preg_split('/(?<!\\\\)[=:]/', $trimmed, 2); if ($parts === false || count($parts) !== 2) { return null; } return [rtrim($parts[0]), ltrim($parts[1])]; } private static function stringify(string|bool|int $value): string { return match (true) { is_bool($value) => $value ? 'true' : 'false', is_int($value) => (string) $value, default => $value, }; } private static function escape(string $value): string { $out = ''; foreach (preg_split('//u', $value, -1, PREG_SPLIT_NO_EMPTY) ?: [] as $character) { $code = mb_ord($character, 'UTF-8'); $out .= match (true) { $character === '\\' => '\\\\', $character === "\n" => '\\n', $character === "\r" => '\\r', $character === "\t" => '\\t', $code === false || $code < 0x20 || $code > 0x7E => sprintf('\\u%04X', (int) $code), default => $character, }; } return preg_replace('/^ /', '\\ ', $out) ?? $out; } private static function unescape(string $value): string { return preg_replace_callback( '/\\\\(u[0-9a-fA-F]{4}|.)/', function (array $match): string { $escape = $match[1]; if (str_starts_with($escape, 'u')) { return mb_chr((int) hexdec(substr($escape, 1)), 'UTF-8') ?: ''; } return match ($escape) { 'n' => "\n", 'r' => "\r", 't' => "\t", default => $escape, }; }, $value, ) ?? $value; } } 